package org.jsoup.helper;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import java.io.UnsupportedEncodingException;
import java.net.MalformedURLException;
import java.net.URL;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class UrlBuilderTest {

    @Mock
    private URL inputUrl;

    @Test
    public void buildTest() throws MalformedURLException {
        when(inputUrl.toString()).thenReturn("https://www.example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        URL result = urlBuilder.build();
        assertEquals("https://www.example.com", result.toString());
    }

    @Test
    public void appendKeyValTest() throws UnsupportedEncodingException {
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        urlBuilder.appendKeyVal(kv);
        assertEquals("key=value", urlBuilder.query());
    }

}
```

This code provides two unit tests for the `build` and `appendKeyVal` methods of the `UrlBuilder` class. The `buildTest` method tests the `build` method by mocking the `inputUrl` and verifying that the returned URL is correct. The `appendKeyValTest` method tests the `appendKeyVal` method by creating a `Connection.KeyVal` object and verifying that the query string is correctly appended.
